#break statement
for i in range(1,10):
    if(i==5):
        break
    print(i)
print('---------------------')

#pass statement
for i in range(1,10):
    if(i==5):
        pass
    #else:
        #print(i)
print('---------------------')

#continue statement
# The continue statement skips the rest of the current loop iteration
# and moves on to the next one. In this loop, when i == 7, the print
# statement is skipped and the loop continues with the next value.
for i in range(1,10):
    if(i==7):
        continue
    print(i)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                